```java
import java.io.*;
import java.nio.file.*;
import java.util.Arrays;
import java.util.List;

// SECURE Example: Path Traversal protection
public class FileHandler {
    private static final String BASE_DIRECTORY = "/app/data/";
    // List of allowed filenames to prevent arbitrary path traversal
    private static final List<String> ALLOWED_FILES = Arrays.asList("report.txt", "info.log", "user.json");

    public void readFile(String userInput) throws IOException {
        // 1. Get the path as a Path object to normalize it
        Path inputPath = Paths.get(userInput).normalize();

        // 2. Validate the filename against a whitelist instead of the whole path
        if (!ALLOWED_FILES.contains(inputPath.getFileName().toString())) {
            throw new SecurityException("Access Denied: Invalid file requested.");
        }

        // 3. Use the safe, normalized path joined to the base directory
        Path finalPath = Paths.get(BASE_DIRECTORY).resolve(inputPath).normalize();

        // 4. Ensure the resolved path actually resides within the BASE_DIRECTORY
        if (!finalPath.startsWith(Paths.get(BASE_DIRECTORY))) {
            throw new SecurityException("Access Denied: Path traversal attempt detected.");
        }

        try (BufferedReader reader = Files.newBufferedReader(finalPath)) {
            String line;
            while ((line = reader.readLine()) != null) {
                System.out.println(line);
            }
        }
    }
}
